@Test
public void verifySimilar_1_oe() {
    final String string1 = "HasSameRef";
    final String string2 = "HasDifferentRef";
    JSONArray obj1 = new JSONArray()
            .put("abc")
            .put(string1)
            .put(2);

    JSONArray obj2 = new JSONArray()
            .put("abc")
            .put(string1)
            .put(3);

    JSONArray obj3 = new JSONArray()
            .put("abc")
            .put(new String(string1))
            .put(2);

    JSONArray obj4 = new JSONArray()
            .put("abc")
            .put(2.0)
    		.put(new String(string1));

    JSONArray obj5 = new JSONArray()
            .put("abc")
            .put(2.0)
    		.put(new String(string2));

    assertFalse("obj1-obj2 Should eval to false", obj1.similar(obj2));
}

mut_method_definition:
public boolean similar(Object other) {
        if (!(other instanceof JSONArray)) {
            return false;
        }
        int len = this.length();
        if (len != ((JSONArray)other).length()) {
            return false;
        }
        for (int i = 0; i < len; i += 1) {
            Object valueThis = this.myArrayList.get(i);
            Object valueOther = ((JSONArray)other).myArrayList.get(i);
            if(valueThis == valueOther) {
            	continue;
            }
            if(valueThis == null) {
            	return false;
            }
            if (valueThis instanceof JSONObject) {
                if (!((JSONObject)valueThis).similar(valueOther)) {
                    return false;
                }
            } else if (valueThis instanceof JSONArray) {
                if (!((JSONArray)valueThis).similar(valueOther)) {
                    return false;
                }
            } else if (valueThis instanceof Number && valueOther instanceof Number) {
                if (!JSONObject.isNumberSimilar((Number)valueThis, (Number)valueOther)) {
                	return false;
                }
            } else if (valueThis instanceof JSONString && valueOther instanceof JSONString) {
                if (!((JSONString) valueThis).toJSONString().equals(((JSONString) valueOther).toJSONString())) {
                    return false;
                }
            } else if (!valueThis.equals(valueOther)) {
                return false;
            }
        }
        return true;
    }

