        "["+
            "hello,"+
            "world"+
        "]";
    // 2
    jsonArray.put(new JSONArray(jsonArrayStr));

    // 3
    jsonArray.put(2.5);
    // 4
    jsonArray.put(1);
    // 5
    jsonArray.put(45L);

    // 6
